var schools = [["Combat Technique", "sword", "blade", "weapon", "strik", "attack", "technique", "swing", "fighting", "combat", "punch", "fist", "spear", "axe", "staff"], ["Defense", "defen", "guard", "parry", "block", "shield", "dodg", "brace"], ["Tactics", "tactic", "strateg", "formation", "command", "drill the squad", "battlefield", "positioning"], ["Focus", "focus", "concentrat", "meditat", "channel", "casting", "breathing"], ["Athletic Mobility", "mobility", "footwork", "run", "climb", "vault", "sprint", "agility", "acrobat", "leap"], ["Banter", "banter", "taunt", "mock", "jeer", "insult", "quip", "heckl", "trash talk", "roast", "comeback"]];
