if (!hit) {
  var sources = [["practice", 0, ["train", "drill", "practi", "spar", "exercise", "repetition", "rehears", "in the field"]], ["teacher", 12, ["teach", "taught", "lesson", "tutor", "mentor", "instruct", "class", "shows me", "show me", "coach", "apprentice", "learn from", "with master"]], ["book", 7, ["book", "tome", "scroll", "manual", "treatise", "read", "study", "librar", "text", "notes", "manuscript", "grimoire", "journal"]]]; var nxt = {"book": "a teacher, or practice in the field", "teacher": "practice in the field"}; var src = null;
  for (var si = 0; si < sources.length && !src; si++) { for (var ci = 0; ci < sources[si][2].length; ci++) { if (text.indexOf(sources[si][2][ci]) >= 0) { src = sources[si]; break; } } }
  if (!src) { for (var di = 0; di < sources.length; di++) { if (sources[di][0] === "teacher") { src = sources[di]; } } }
  var stop = ["the", "and", "with", "from", "for", "about", "into", "while", "then", "that", "this", "these", "those", "some", "more", "myself", "himself", "herself", "own", "new", "old", "how", "what", "all", "any", "one", "two", "few", "day", "days", "hour", "hours", "night", "week", "time", "until", "under", "over", "again", "skill", "skills", "level", "levels", "art", "arts", "way", "ways", "basics", "secrets", "lore", "theory", "craft", "book", "books", "tome", "scroll", "manual", "treatise", "librar", "library", "text", "texts", "notes", "manuscript", "grimoire", "journal", "lesson", "lessons", "teacher", "tutor", "mentor", "master", "class", "coach", "apprentice", "him", "her", "them", "his", "their", "our", "your", "mine", "she", "they", "you", "ask", "asks", "help", "helps", "try", "tries", "want", "wants", "spend", "spends", "keep", "start", "begin"]; var cues = []; for (var qi = 0; qi < sources.length; qi++) { cues = cues.concat(sources[qi][2]); }
  var words = text.replace(/[^a-z0-9' -]/g, ' ').split(/\s+/).filter(function (w) { if (w.length < 3 || stop.indexOf(w) >= 0) { return false; } for (var k = 0; k < cues.length; k++) { if (w.indexOf(cues[k]) === 0) { return false; } } return true; });
  var names = []; for (var wi = 0; wi < words.length; wi++) { names.push(words[wi]); if (wi + 1 < words.length) { names.push(words[wi] + ' ' + words[wi + 1]); } }
  function cap1(v) { return v.replace(/(^|\s)([a-z])/g, function (m, a, b) { return a + b.toUpperCase(); }); }
  function asMap(v) { return (v !== null && typeof v === 'object' && !Array.isArray(v)) ? v : (typeof v === 'number' ? {'the character': v} : {}); }
  var found = null; var levels = null;
  for (var ni = 0; ni < names.length && ni < 12 && !found; ni++) { var tries = [names[ni], cap1(names[ni])];
